        XPathParser parser = new XPathParser(new StringReader(input));
        setCompiler(parser, compiler.proxy);
        return parser.WildcardName();
    }

    private void assertParseException(String input) throws Exception {
        try {
            parse(input, new RecordingCompiler());
            fail("Expected ParseException for input: " + input);
        } catch (ParseException expected) {
            // Expected.
        }
    }

    private void setCompiler(XPathParser parser, Compiler compiler) throws Exception {
        Class<?> type = parser.getClass();

        while (type != null) {
            Field[] fields = type.getDeclaredFields();

            for (Field field : fields) {
                if (Compiler.class.isAssignableFrom(field.getType())) {
                    field.setAccessible(true);
                    field.set(parser, compiler);
                    return;
                }
            }

            type = type.getSuperclass();
        }

        fail("XPathParser does not contain a Compiler field");
    }

    private static final class RecordingCompiler implements InvocationHandler {
        private final Compiler proxy;
        private int callCount;
        private String namespace;
        private String localName;

        private RecordingCompiler() {
            proxy = (Compiler) Proxy.newProxyInstance(
                    Compiler.class.getClassLoader(),
                    new Class<?>[] {Compiler.class},
                    this);
        }

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) {
            if ("qname".equals(method.getName())) {
                callCount++;
                namespace = (String) args[0];
                localName = (String) args[1];
                return QNAME_RESULT;
            }

            if ("toString".equals(method.getName())) {
                return "RecordingCompiler";
            }

            if ("hashCode".equals(method.getName())) {
                return System.identityHashCode(proxy);
            }

            if ("equals".equals(method.getName())) {
                return proxy == args[0];
            }

            return null;
        }
    }
